#!/usr/bin/env python3
"""Write docs/settings-reference.md from the surfd.toml schema and defaults.

    python3 tools/gen_settings_doc.py > docs/settings-reference.md
"""

from __future__ import annotations

import json
import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src" / "surfctl"))

from surfd import keys, schema  # noqa: E402


def main() -> int:
    defaults = tomllib.loads((ROOT / "config" / "defaults" / "surfd.toml").read_text())
    out = ["# surfd.toml settings reference", "",
           "<!-- Generated by tools/gen_settings_doc.py from the schema; do not edit by hand. -->", "",
           "Every key, its default and what it accepts. Change any of them with",
           "`surfctl set <key> <value>`, in Surf Settings, or by editing",
           "`~/.config/surfd/surfd.toml` and running `surfctl reload`.", ""]
    for section in schema.sections():
        out += [f"## [{section}]", "", "| Key | Default | Accepts | Description |", "|---|---|---|---|"]
        for dotted, fld in schema.SCHEMA.items():
            if not dotted.startswith(section + "."):
                continue
            key = dotted.split(".", 1)[1]
            default = defaults[section][key]
            if fld.choices:
                accepts = " \\| ".join(f"`{c}`" for c in fld.choices)
            elif fld.kind in ("int", "float"):
                accepts = f"{fld.kind} {fld.minimum:g}–{fld.maximum:g}"
            elif fld.kind == "modules":
                accepts = "list of bar modules"
            elif fld.kind == "color?":
                accepts = '`""` or `"#rrggbb"`'
            else:
                accepts = {"bool": "true / false", "list": "list of strings"}.get(fld.kind, "text")
            shown = ("true" if default else "false") if isinstance(default, bool) else json.dumps(default)
            out.append(f"| `{key}` | `{shown}` | {accepts} | {fld.help.replace('|', '/')} |")
        out.append("")
    out += ["## [keys.bindings]", "",
            "`\"<combo>\" = \"<action>\"`. `Mod` means `keys.modifier`. Set an action to `\"none\"` to",
            "disable a default binding.", "", "| Action | What it does |", "|---|---|"]
    for name, a in keys.ACTIONS.items():
        out.append(f"| `{name}` | {a.description} |")
    out += ["| `focus left\\|right\\|up\\|down` | Move focus |",
            "| `move left\\|right\\|up\\|down` | Move the window |",
            "| `workspace N` | Go to workspace N |",
            "| `move-to-workspace N` | Send the window to workspace N |",
            "| `exec <command>` | Run a command (no `;` or `,`: use a script) |",
            "| `sway <command>` | Any raw Sway command |", "",
            "## Bar modules", "", "| Module | Shows |", "|---|---|"]
    for m, desc in schema.BAR_MODULES.items():
        out.append(f"| `{m}` | {desc} |")
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
